'use client';
import {useEffect,useRef,useState,type ReactNode} from 'react';
import {LayoutDashboard,Users,BookOpen,ClipboardList,MessageSquare,Bell,CalendarDays,Trophy,ChartNoAxesCombined,Settings,ChevronLeft,Plus,Search,ArrowUpLeft,Clock,MapPin,GraduationCap,Check,FileText,Upload,Send,X,Menu,MoreHorizontal,Archive,RotateCcw,CreditCard,Link2,ShieldCheck,Download,ChevronDown,ExternalLink,TriangleAlert,Activity,Layers,ArrowRight,CheckCircle2,School,Sparkles,FolderOpen,UserRound,PanelRightClose} from 'lucide-react';
import {createSeed,actorOf,groupsFor,statsFor,visibleState,isEligible,demoActors,roleLabels,type State,type Row,type Role} from '../lib/platform-model';
import {applyAction} from '../lib/platform-actions';
import {compressPhoto,photoDataUrl} from '../lib/compress-photo';
import {signOut} from 'firebase/auth';
import {firebaseAuth} from '../lib/firebase-client';
import {emptyPortal,watchPortal,savePortalAction,downloadPhoto,cleanPortalPhotos,portalError} from '../lib/portal-client';
import PortalAdmin from './portal-admin';
import {readLocal,saveLocal} from '../lib/local-preview';
import {cleanLocalPhotos,expiresAt} from '../lib/photo-policy';
const statusNames:Record<string,string>={pending:'بانتظار المراجعة',complete:'مكتمل ومعتمد',revision:'محتاج تعديل',missing:'لم يتم التسليم',paid:'تم الدفع',unpaid:'لم يتم الدفع',pending_parent:'بانتظار ولي الأمر',pending_admin:'بانتظار الإدارة',approved:'تمت الموافقة'};
const fmt=(d:string)=>d?new Date(d+'T12:00:00').toLocaleDateString('ar-EG',{day:'numeric',month:'short'}):'—';
const time=(v:string)=>{const [h,m]=v.split(':');return `${(+h%12)||12}:${m} ${+h>=12?'م':'ص'}`;};
const initials=(name:string)=>name.split(' ').slice(0,2).map(x=>x[0]).join('');
function Avatar({user,small=false}:{user?:Row;small?:boolean}){return <span className={`avatar ${user?.color||'blue'} ${small?'small':''}`}>{initials(user?.name||'ت و')}</span>;}
function Badge({status,children}:{status?:string;children?:ReactNode}){return <span className={`badge ${status||''}`}>{children||statusNames[status||'']||status}</span>;}
function Empty({title='مفيش عناصر هنا لسه',description='لما يتضاف محتوى جديد، هيظهر في المكان ده.'}:{title?:string;description?:string}){return <div className="empty"><FolderOpen size={34}/><h3>{title}</h3><p>{description}</p></div>;}
function Progress({value}:{value:number}){return <div className="progress"><span style={{width:Math.max(0,Math.min(100,value))+'%'}}/></div>;}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>;}
export default function Platform({liveUid}:{liveUid?:string}){
 const [data,setData]=useState<State>(()=>liveUid?emptyPortal():createSeed()),[actorId,setActorId]=useState(liveUid||'a1'),[page,setPage]=useState('dashboard'),[groupId,setGroupId]=useState('g1'),[groupTab,setGroupTab]=useState('sessions'),[childId,setChildId]=useState(liveUid?'':'s1');
 const [query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[modal,setModal]=useState<Row|null>(null),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[persistent,setPersistent]=useState(false),[revision,setRevision]=useState(0),[toast,setToast]=useState(''),[mobile,setMobile]=useState(false),[chatKey,setChatKey]=useState('g1:s1'),[draft,setDraft]=useState(''),[liveError,setLiveError]=useState('');
 const local=useRef(createSeed()),loaded=useRef(false),requestSeq=useRef(0),cleaned=useRef(false),toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const actor:Row=data.users.find(x=>x.id===actorId)||(liveUid?{id:liveUid,role:'student',name:'جاري التحميل'}:undefined)||demoActors.find(x=>x.id===actorId)||{id:'a1',role:'admin',name:'إدارة Techware'};const role=actor.role as Role,admin=role==='admin',teacher=role==='instructor'||admin,parent=role==='parent',student=role==='student';
 const groups=groupsFor(data,actor),me=parent?childId:actorId,selectedStudent=data.users.find(x=>x.id===me),group=data.groups.find(g=>g.id===groupId),user=(id:string)=>data.users.find(u=>u.id===id),course=(id:string)=>data.courses.find(c=>c.id===id),groupName=(id:string)=>data.groups.find(g=>g.id===id)?.name||'الأكاديمية';
 const relevantGroups=parent?groups.filter(g=>g.studentIds.includes(childId)):groups;const unread=data.notifications.filter(n=>n.userId===actorId&&!n.read).length;
 const pending=data.submissions.filter(s=>s.status==='pending'),allStudents=data.users.filter(u=>u.role==='student');
 function say(text:string){setToast(text);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),5000);}
 async function load(id=actorId,silent=false){const seq=++requestSeq.current;if(!silent)setLoading(true);try{if((window as Window & {__TECHWARE_STATIC__?:boolean}).__TECHWARE_STATIC__){if(!loaded.current){const saved=await readLocal();if(saved)local.current=saved;}local.current=cleanLocalPhotos(local.current);await saveLocal(local.current);if(seq!==requestSeq.current)return;setData(visibleState(local.current,actorOf(local.current,id)));setPersistent(false);loaded.current=true;return;}const r=await fetch('/api/workspace?actor='+encodeURIComponent(id),{cache:'no-store'});const d:any=await r.json();if(!r.ok)throw Error(d.error);if(seq!==requestSeq.current)return;if(d.persistent){setData(d.state);setPersistent(true);}else{if(!loaded.current){const saved=await readLocal();if(saved)local.current=saved;}local.current=cleanLocalPhotos(local.current);await saveLocal(local.current);setData(visibleState(local.current,actorOf(local.current,id)));setPersistent(false);}setRevision(d.revision);loaded.current=true;}catch(e){say(e instanceof Error?e.message:'تعذّر تحميل البيانات');}finally{if(seq===requestSeq.current)setLoading(false);}}
 useEffect(()=>{if(liveUid)return watchPortal(liveUid,s=>{setData(s);setLoading(false);setLiveError('');},e=>{setLiveError(portalError(e));setLoading(false);});load(actorId);},[actorId,liveUid]);
 useEffect(()=>{if(liveUid&&actor.role==='parent'&&!actor.children?.includes(childId))setChildId(actor.children?.[0]||'');},[data.users,liveUid]);
 useEffect(()=>{const id=setInterval(()=>{if(loaded.current&&persistent&&!busy&&!modal)load(actorId,true);},15000);return()=>clearInterval(id);},[actorId,persistent,busy,modal]);
 useEffect(()=>{if(!liveUid||role!=='admin'||loading||cleaned.current)return;cleaned.current=true;const key='techware-photo-cleanup-'+liveUid;let last=0;try{last=Number(localStorage.getItem(key));}catch{}if(Date.now()-last<86400000)return;cleanPortalPhotos().then(n=>{try{localStorage.setItem(key,String(Date.now()));}catch{}if(n)say('تم تنظيف '+n+' صورة قديمة مع الاحتفاظ بنتائج التاسكات.');}).catch(e=>say('التنظيف لم يكتمل: '+portalError(e)));},[liveUid,role,loading]);
 function navigate(p:string){setPage(p);setQuery('');setFilter('all');setMobile(false);}
 function switchRole(id:string){requestSeq.current++;setActorId(id);setData(visibleState(local.current,actorOf(local.current,id)));setModal(null);setPage('dashboard');setQuery('');setChildId('s1');setFilter('all');setChatKey(id==='t2'?'g2:s2':'g1:s1');}
 async function mutate(type:string,payload:Row,close=true){if(busy)return;setBusy(true);try{if(liveUid){await savePortalAction(data,liveUid,type,payload);}else if(persistent){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:actorId,revision,action:{type,payload}})});const d:any=await r.json();if(!r.ok){if(r.status===409)await load(actorId,true);throw Error(d.error);}setData(d.state);setRevision(d.revision);}else{const next=cleanLocalPhotos(applyAction(local.current,actorId,{type,payload}));await saveLocal(next);local.current=next;setData(visibleState(local.current,actorOf(local.current,actorId)));}if(close)setModal(null);say(liveUid||persistent?'تم حفظ التغيير':'تم التحديث في المعاينة المحلية');return true;}catch(e){say(liveUid?portalError(e):e instanceof Error?e.message:'تعذّر الحفظ');return false;}finally{setBusy(false);}}
 async function formSubmit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!modal)return;const f=new FormData(e.currentTarget),p:Row=Object.fromEntries(f.entries());let type=modal.type;
 if(type==='saveGroup'){p.studentIds=f.getAll('studentIds');if(modal.item?.id)p.id=modal.item.id;}
 if(type==='submitTask'){p.taskId=modal.item.id;p.files=[];const files=f.getAll('files').filter((v):v is File=>v instanceof File&&v.size>0);if(files.length>5)return say('الحد الأقصى 5 ملفات لكل تسليم');if(files.length){setBusy(true);try{for(const original of files){const file=await compressPhoto(original,liveUid?220000:undefined);if(!persistent){p.files.push({id:crypto.randomUUID(),name:file.name,size:file.size,mime:file.type,dataUrl:await photoDataUrl(file)});continue;}const form=new FormData();form.set('file',file);form.set('actor',actorId);form.set('taskId',p.taskId);const r=await fetch('/api/files',{method:'POST',body:form});const d:any=await r.json();if(!r.ok)throw Error(d.error);p.files.push(d);}}catch(error){say(error instanceof Error?error.message:'تعذّر رفع الملف');setBusy(false);return;}setBusy(false);}}
 if(['reviewSubmission','recordPayment'].includes(type))p.id=modal.item.id;if(type==='reviewSubmission')p.keepPhotos=f.get('keepPhotos')==='on';
 if(type==='saveCompetition')p.courseIds=f.getAll('courseIds');
 await mutate(type,p);
 }
 function openGroup(g:Row,tab='sessions'){setGroupId(g.id);setGroupTab(tab);navigate('group');}
 function exportReport(){const rows=[['الطالب','المجموعة','الكورس','المستوى','المحاضرة','التاسكات المطلوبة','تم إرسالها','معتمدة','نسبة الإرسال']];groups.forEach(g=>g.studentIds.forEach((id:string)=>{const st=statsFor(data,id,g.id);rows.push([user(id)?.name||id,g.name,course(g.courseId)?.name||'',String(g.level),String(g.session),String(st.required),String(st.sent),String(st.complete),st.percent+'%']);}));const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='Techware_Progress_Report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
 const nav=[{id:'dashboard',label:'نظرة عامة',icon:LayoutDashboard},{id:'groups',label:teacher?'المجموعات':'مجموعاتي',icon:Users},{id:'tasks',label:teacher?'التاسكات والمراجعات':'التاسكات',icon:ClipboardList,count:teacher?pending.length:undefined},{id:'journey',label:teacher?'المسارات التعليمية':'رحلة التعلّم',icon:GraduationCap},...(!parent?[{id:'messages',label:'الرسائل',icon:MessageSquare,count:data.notifications.filter(n=>n.userId===actorId&&n.kind==='message'&&!n.read).length}]:[]),{id:'events',label:'المواعيد والأحداث',icon:CalendarDays},{id:'competitions',label:'المسابقات',icon:Trophy},...((admin||parent)?[{id:'payments',label:'المستويات والمدفوعات',icon:CreditCard}]:[]),...(liveUid&&admin?[{id:'accounts',label:'الحسابات والكورسات',icon:Settings}]:[]),...(admin?[{id:'analytics',label:'إحصائيات الأكاديمية',icon:ChartNoAxesCombined},{id:'integrations',label:'الأنظمة والربط',icon:Link2}]:[])];
 const titles:Record<string,string>={dashboard:admin?'نظرة على الأكاديمية':teacher?'كل مجموعاتك، في مكان واحد':parent?'متابعة أولادك، خطوة بخطوة':'جاهز لخطوتك الجاية؟',groups:teacher?'المجموعات':'مجموعاتي',group:group?.name||'المجموعة',tasks:teacher?'التاسكات والمراجعات':'تاسكاتي',journey:teacher?'المسارات التعليمية':'رحلة التعلّم',messages:'الرسائل',events:'المواعيد والأحداث',competitions:'فرص وتحديات جديدة',payments:'المستويات والمدفوعات',analytics:'إحصائيات الأكاديمية',accounts:'إدارة الحسابات والكورسات',integrations:'أنظمة Techware في مكان واحد',notifications:'الإشعارات'};
 const commonAction=admin?<button className="btn primary" onClick={()=>setModal({type:'saveGroup'})}><Plus size={17}/>مجموعة جديدة</button>:role==='instructor'?<button className="btn primary" onClick={()=>setModal({type:'publishSession',item:groups[0]})}><Plus size={17}/>ملخص سيشن جديد</button>:<button className="btn primary" onClick={()=>navigate('tasks')}>شوف التاسكات<ArrowUpLeft size={17}/></button>;
 function Stat({label,value,detail,icon:Icon,color='blue'}:{label:string;value:string|number;detail:string;icon:any;color?:string}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={`icon-box ${color}`}><Icon size={20}/></span></div><strong>{value}</strong><small>{detail}</small></div>;}
 function GroupCard({g}:{g:Row}){const c=course(g.courseId),count=data.submissions.filter(s=>s.status==='pending'&&data.tasks.some(t=>t.id===s.taskId&&t.groupId===g.id)).length;return <button className="group-card" onClick={()=>openGroup(g)}><div className="group-top"><span className={`course-icon ${c?.color||'blue'}`}>{c?.name==='Python'?<span className="code-mark">{'{ }'}</span>:c?.id==='steam'?<Layers size={26}/>:<School size={26}/>}</span><span className="group-course">{c?.name}<small>{g.room} · {g.studentIds.length} من 8 طلاب</small></span><ChevronLeft size={18}/></div><h3>{g.name.split(' · ')[1]||g.name}</h3><p><CalendarDays size={14}/>{g.day}<span className="dot"/><Clock size={14}/>{time(g.time)} · ساعتين</p><div className="group-progress"><span>المستوى {g.level}</span><span>المحاضرة {g.session} / 4</span></div><div className="session-steps">{[1,2,3,4].map(n=><span key={n} className={n<=g.session?'done':''}/>)}</div><div className="group-foot"><span><Avatar user={user(g.instructorId)} small/>{user(g.instructorId)?.name}</span>{teacher&&count?<Badge status="pending">{count} للمراجعة</Badge>:<span className="open-link">فتح المجموعة<ArrowUpLeft size={14}/></span>}</div></button>;}
 function LessonCard({l}:{l:Row}){return <details className="lesson-card"><summary><span className="lesson-number">{l.number.toString().padStart(2,'0')}</span><div><small>المستوى {l.level} · {fmt(l.date)}</small><h3 dir="auto">{l.title}</h3></div><Badge status="complete">ملخص متاح</Badge><ChevronDown size={17}/></summary><div className="lesson-content"><span className="eyebrow">ملخص السيشن</span><p>{l.summary}</p>{l.taskText&&<div className="task-callout"><b>التاسك المطلوب</b><p>{l.taskText}</p></div>}{teacher&&<button className="btn subtle" onClick={()=>setModal({type:'publishSession',item:data.groups.find(g=>g.id===l.groupId),lesson:l})}>تعديل الملخص</button>}</div></details>;}
 function TaskCard({task:t}:{task:Row}){const sub=data.submissions.find(x=>x.taskId===t.id&&x.studentId===me),g=data.groups.find(g=>g.id===t.groupId);return <article className="task-card"><div className="row spread"><span className="tiny">{g?.name}</span><Badge status={sub?.status||'missing'}/></div><h3 dir="auto">{t.title}</h3><p>{t.description}</p><div className="row spread"><small className="row"><Clock size={15}/>آخر تسليم {fmt(t.due)}</small><button className="btn small-btn" onClick={()=>setModal({type:student?'submitTask':'viewSubmission',item:t,submission:sub})}>{student?(sub?.status==='complete'?'عرض التسليم':sub?'تحديث التسليم':'إرسال التاسك'):'عرض التسليم'}<ArrowUpLeft size={15}/></button></div>{sub?.feedback&&<div className="feedback"><MessageSquare size={15}/><span>{sub.feedback}</span></div>}</article>;}
 function ReviewTable({gid}:{gid?:string}){const items=data.submissions.filter(s=>(filter==='all'||s.status===filter)&&(!gid||data.tasks.some(t=>t.id===s.taskId&&t.groupId===gid))).filter(s=>`${user(s.studentId)?.name} ${data.tasks.find(t=>t.id===s.taskId)?.title}`.toLowerCase().includes(query.toLowerCase()));return <><div className="filter-row">{[['all','الكل'],['pending','بانتظار المراجعة'],['revision','محتاج تعديل'],['complete','مكتمل']].map(([v,l])=><button key={v} className={filter===v?'chip active':'chip'} onClick={()=>setFilter(v)}>{l}</button>)}</div>{!items.length?<Empty title="مفيش تسليمات بالحالة دي"/>:<div className="table-wrap"><table><thead><tr><th>الطالب</th><th>التاسك / المجموعة</th><th>التسليم</th><th>الحالة</th><th/></tr></thead><tbody>{items.map(s=>{const t=data.tasks.find(t=>t.id===s.taskId);return <tr key={s.id}><td><span className="row"><Avatar user={user(s.studentId)} small/><b>{user(s.studentId)?.name}</b></span></td><td><b dir="auto">{t?.title}</b><small className="block">{groupName(t?.groupId)}</small></td><td>{fmt(s.submittedAt.slice(0,10))}<small className="block">المحاولة {s.attempt}</small></td><td><Badge status={s.status}/></td><td><button className="btn subtle small-btn" onClick={()=>setModal({type:'reviewSubmission',item:s,task:t})}>مراجعة<ChevronLeft size={15}/></button></td></tr>;})}</tbody></table></div>}</>;}
 const dashboard=()=>{const myStats=statsFor(data,me),totalReq=groups.reduce((n,g)=>n+g.studentIds.length*data.tasks.filter(t=>t.groupId===g.id&&t.required!==false).length,0),percent=totalReq?Math.round(data.submissions.length/totalReq*100):0;return <>
 <div className="hero"><div><span className="eyebrow">TECHWARE LEARNING SPACE</span><h2>{teacher?'مساحة لكل طالب.. وخطوة لكل إنجاز.':'كل محاولة بتعلّمك حاجة جديدة.'}</h2><p>{teacher?'تابع التعلّم، شجّع المحاولات، وخلّي كل خطوة واضحة.':'محاضراتك، مشاريعك، وخطوتك الجاية.. كلهم هنا.'}</p><span className="hero-note"><span className="status-dot"/>الروبوت مش الهدف… الإنسان هو الهدف.</span></div><div className="hero-art" aria-hidden="true"><div className="orbital o1"/><div className="orbital o2"/><div className="learning-tile"><Layers size={48}/><span>LEARN. BUILD. GROW.</span></div><span className="art-chip ac1"><CheckCircle2 size={18}/>خطوة أقرب</span><span className="art-chip ac2"><Sparkles size={16}/>فكرة جديدة</span></div></div>
 <div className="stats-grid">{teacher?<><Stat label="الطلاب" value={allStudents.length} detail="طلاب المجموعات النشطة" icon={Users}/><Stat label="المجموعات" value={groups.length} detail="4 محاضرات في كل مستوى" icon={Layers} color="violet"/><Stat label="بانتظار المراجعة" value={pending.length} detail="تسليمات محتاجة ملاحظتك" icon={ClipboardList} color="orange"/><Stat label="نسبة إرسال التاسكات" value={percent+'%'} detail={`${data.submissions.length} من ${totalReq} تكليفًا للطلاب`} icon={ChartNoAxesCombined} color="green"/></>:<><Stat label="التاسكات اللي اتبعتت" value={`${myStats.sent} / ${myStats.required}`} detail="عدد الإرسالات من المطلوب" icon={Upload}/><Stat label="نسبة الإرسال" value={myStats.percent+'%'} detail="كل تاسك بيتحسب مرة واحدة" icon={ChartNoAxesCombined} color="violet"/><Stat label="تاسكات معتمدة" value={myStats.complete} detail="راجعها المدرب واعتمدها" icon={CheckCircle2} color="green"/><Stat label="الكورسات المكتملة" value={selectedStudent?.completed?.length||0} detail="رحلة مستمرة من المهارات" icon={GraduationCap} color="orange"/></>}</div>
 <div className="dashboard-columns"><div><div className="section-head"><h2>{teacher?'المجموعات النشطة':'مجموعاتي'}</h2><button className="text-btn" onClick={()=>navigate('groups')}>عرض الكل<ChevronLeft size={16}/></button></div><div className="group-grid">{relevantGroups.slice(0,4).map(g=><GroupCard g={g} key={g.id}/>)}</div><div className="panel next-panel"><div className="section-head"><h2>{teacher?'التاسكات اللي محتاجة متابعة':'آخر المحاضرات'}</h2><button className="text-btn" onClick={()=>navigate(teacher?'tasks':'groups')}>عرض الكل<ChevronLeft size={16}/></button></div>{teacher?<div>{pending.slice(0,3).map(s=><button className="attention-row" key={s.id} onClick={()=>setModal({type:'reviewSubmission',item:s,task:data.tasks.find(t=>t.id===s.taskId)})}><Avatar user={user(s.studentId)} small/><div><b>{user(s.studentId)?.name}</b><small>{data.tasks.find(t=>t.id===s.taskId)?.title}</small></div><Badge status="pending"/><ChevronLeft size={16}/></button>)}{!pending.length&&<Empty title="كل التسليمات متراجعة"/>}</div>:data.sessions.filter(l=>relevantGroups.some(g=>g.id===l.groupId)).slice(-2).reverse().map(l=><LessonCard l={l} key={l.id}/>)}</div></div><aside className="dashboard-side"><div className="panel"><div className="section-head"><h2>على الجدول</h2><CalendarDays size={19}/></div>{!liveUid&&<><div className="week-row">{['س','ح','ن','ث','ر','خ','ج'].map((x,i)=><div className={i===5?'today':''} key={i}><small>{x}</small><b>{17+i}</b></div>)}</div><small className="tiny">أسبوع توضيحي · أكتوبر 2026</small></>}{relevantGroups.slice(0,3).map(g=><button className="schedule-row" onClick={()=>openGroup(g)} key={g.id}><span className="schedule-time">{time(g.time)}<small>{g.day}</small></span><span className="schedule-line"/><span><b>{course(g.courseId)?.name}</b><small>{g.room} · المحاضرة {g.session}</small></span></button>)}</div><div className="event-card"><span className="event-icon"><Bell size={22}/></span><small>خليك على اطلاع</small><h3>{data.events[0]?.title||'مفيش تحديثات استثنائية'}</h3><p>{data.events[0]?.description||'أي إجازة أو تغيير في المعاد هتلاقيه هنا.'}</p><button className="text-btn" onClick={()=>navigate('events')}>تفاصيل الأحداث<ArrowUpLeft size={16}/></button></div><div className="mini-manifesto"><span>من فكرة.. لمهارة.</span><p>التقدم بيتقاس بالمحاولة والفهم، مش بالنتيجة بس.</p></div></aside></div></>;};
 function Journey(){return <>{!teacher&&<div className="panel student-summary"><Avatar user={selectedStudent}/><div><h2>{selectedStudent?.name}</h2><p>{selectedStudent?.age} سنة · {relevantGroups.length} مجموعة نشطة</p></div><Badge status="complete">كل خطوة ليها قيمة</Badge></div>}{!teacher&&relevantGroups.map(g=><div className="panel journey-panel" key={g.id}><h2>{g.name}</h2><div className="journey-steps"><div className="journey-step completed"><span><Check size={18}/></span><small>أنهيت</small><b>{selectedStudent?.completed?.join(' · ')||'بداية رحلة التعلّم'}</b></div><div className="journey-step current"><span><BookOpen size={18}/></span><small>بتتعلّم دلوقتي</small><b>{course(g.courseId)?.name}</b><p>المستوى {g.level} · المحاضرة {g.session} من 4</p></div><div className="journey-step"><span><ArrowUpLeft size={18}/></span><small>الخطوة اللي بعدها</small><b>{course(g.courseId)?.next}</b><p>بعد إتمام الكورس وتقييم الاستعداد</p></div></div></div>)}<div className="section-head"><h2>مسارات Techware</h2><Badge>4 محاضرات × ساعتين</Badge></div><div className="track-grid">{(liveUid?Array.from(new Set(data.courses.map(c=>c.track))).map(t=>[t,t,'blue']):[['4–5 سنوات','البدايات الفضولية','green'],['6–9 سنوات','الاكتشاف والتجربة','orange'],['10 سنوات فأكثر','البناء والبرمجة','blue']]).map(([track,label,color])=><div className={'panel track '+color} key={track}><span className={'icon-box '+color}><GraduationCap size={24}/></span><small>{track}</small><h2>{label}</h2>{data.courses.filter(c=>c.track===track).map((c,i)=><div className="track-item" key={c.id}><span>{i+1}</span><b>{c.name}</b></div>)}</div>)}</div><div className="info-banner"><Sparkles size={20}/><p>Android App Development باستخدام MIT App Inventor: مسار داخلي بترشيح المدرب بعد الاستعداد، 6 مستويات، مع إضافة AI في المستويين 5 و6.</p></div></>;}
 function GroupDetail(){if(!group)return <Empty/>;const courseInfo=course(group.courseId);return <><div className="panel group-detail-head"><div className="row"><span className={'course-icon '+courseInfo?.color}><BookOpen size={28}/></span><div><h2>{courseInfo?.name}</h2><p>المستوى {group.level} · المحاضرة {group.session} / 4</p></div></div><div className="detail-facts"><span><CalendarDays size={17}/>{group.day} · {time(group.time)}</span><span><MapPin size={17}/>{group.room}</span><span><Users size={17}/>{group.studentIds.length} / 8</span><span><Avatar user={user(group.instructorId)} small/>{user(group.instructorId)?.name}</span></div>{admin&&<button className="btn" onClick={()=>setModal({type:'saveGroup',item:group})}>تعديل المجموعة</button>}</div><div className="tabs">{[['sessions','المحاضرات'],['tasks','التاسكات'],...(teacher?[['students','الطلاب والحضور'],['notes','الملاحظات']]:parent?[['notes','ملاحظات المدرب']]:[]),...(admin?[['activity','سجل النشاط']]:[])].map(([k,l])=><button key={k} className={groupTab===k?'active':''} onClick={()=>{setGroupTab(k);setFilter('all');}}>{l}</button>)}</div>
 {groupTab==='sessions'&&<div className="panel"><div className="section-head"><h2>أرشيف المحاضرات</h2>{teacher&&<button className="btn primary small-btn" onClick={()=>setModal({type:'publishSession',item:group})}><Plus size={16}/>ملخص جديد</button>}</div>{data.sessions.filter(l=>l.groupId===group.id).sort((a,b)=>b.date.localeCompare(a.date)).map(l=><LessonCard key={l.id} l={l}/>)}{!data.sessions.some(l=>l.groupId===group.id)&&<Empty/>}</div>}
 {groupTab==='tasks'&&(teacher?<div className="panel"><ReviewTable gid={group.id}/></div>:<div className="task-grid">{data.tasks.filter(t=>t.groupId===group.id).map(t=><TaskCard key={t.id} task={t}/>)}</div>)}
 {groupTab==='students'&&teacher&&<div className="panel"><div className="section-head"><h2>طلاب المجموعة</h2><small>الحضور لآخر محاضرة منشورة</small></div><div className="table-wrap"><table><thead><tr><th>الطالب</th><th>إرسال التاسكات</th><th>معتمدة</th><th>الحضور</th><th/></tr></thead><tbody>{group.studentIds.map((id:string)=>{const st=statsFor(data,id,group.id),lesson=data.sessions.filter(l=>l.groupId===group.id).sort((a,b)=>b.date.localeCompare(a.date))[0],att=data.attendance.find(x=>x.studentId===id&&x.sessionId===lesson?.id);return <tr key={id}><td><span className="row"><Avatar user={user(id)} small/><b>{user(id)?.name}</b></span></td><td><b>{st.percent}%</b><small className="block">{st.sent} من {st.required}</small><Progress value={st.percent}/></td><td>{st.complete}</td><td>{lesson?<select aria-label={'حضور '+user(id)?.name} value={att?.status||''} disabled={busy} onChange={e=>mutate('saveAttendance',{studentId:id,sessionId:lesson.id,status:e.target.value},false)}><option value="" disabled>غير مسجل</option><option value="present">حاضر</option><option value="absent">غائب</option><option value="excused">غياب بعذر</option></select>:'لا توجد محاضرات'}</td><td><button className="btn subtle small-btn" onClick={()=>{setChatKey(group.id+':'+id);navigate('messages');}}>رسالة<MessageSquare size={15}/></button></td></tr>;})}</tbody></table></div></div>}
 {groupTab==='notes'&&<div className="panel"><div className="section-head"><h2>ملاحظات ومتابعة</h2>{teacher&&<button className="btn primary small-btn" onClick={()=>setModal({type:'saveNote',item:group})}><Plus size={16}/>ملحوظة</button>}</div>{data.notes.filter(n=>n.groupId===group.id&&(!parent||n.studentId===childId)).map(n=><div className="note" key={n.id}><div className="row spread"><b>{user(n.studentId)?.name}</b><Badge>{n.visibility==='parent'?'تظهر لولي الأمر':'داخلية للإدارة والمدرب'}</Badge></div><p>{n.text}</p><small>{user(n.authorId)?.name} · {fmt(n.createdAt.slice(0,10))}</small></div>)}{!data.notes.some(n=>n.groupId===group.id&&(!parent||n.studentId===childId))&&<Empty title="مفيش ملاحظات حاليًا"/>}</div>}
 {groupTab==='activity'&&admin&&<div className="panel">{data.audit.filter(x=>x.groupId===group.id).map(x=><div className="activity-row" key={x.id}><Activity size={17}/><div><b>{x.action}</b><small>{user(x.actorId)?.name} · {fmt(x.createdAt.slice(0,10))}</small></div></div>)}</div>}
 </>;}
 function Messages(){const conversations=groups.flatMap(g=>(student?[actorId]:g.studentIds).map((id:string)=>({key:g.id+':'+id,g,id})));const selected=conversations.find(x=>x.key===chatKey)||conversations[0];if(!selected)return <Empty title="مفيش محادثات متاحة"/>;const msgs=data.messages.filter(m=>m.groupId===selected.g.id&&m.studentId===selected.id);return <div className="chat-panel"><div className="conversation-list"><div className="chat-list-head"><h3>المحادثات</h3><small>رسائل خاصة داخل المجموعة</small></div>{conversations.map(c=><button key={c.key} className={'conversation '+(c.key===selected.key?'selected':'')} onClick={()=>setChatKey(c.key)}><Avatar user={user(student?c.g.instructorId:c.id)} small/><span><b>{user(student?c.g.instructorId:c.id)?.name}</b><small>{c.g.name}</small><p>{data.messages.filter(m=>m.groupId===c.g.id&&m.studentId===c.id).at(-1)?.text||'ابدأ المحادثة'}</p></span></button>)}</div><div className="chat-main"><div className="chat-head"><Avatar user={user(student?selected.g.instructorId:selected.id)} small/><div><h3>{user(student?selected.g.instructorId:selected.id)?.name}</h3><small>{selected.g.name}</small></div><Badge>محادثة خاصة</Badge></div><div className="chat-notice"><ShieldCheck size={14}/>الإدارة تقدر تراجع المحادثة للمتابعة.</div><div className="bubbles">{msgs.map(m=><div key={m.id} className={'bubble '+(m.senderId===actorId?'mine':'')}><small>{user(m.senderId)?.name}</small><p>{m.text}</p><time>{new Date(m.createdAt).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit',timeZone:'Africa/Cairo'})}</time></div>)}{!msgs.length&&<Empty title="ابدأ برسالة" description="السؤال خطوة مهمة في التعلّم."/>}</div><form className="chat-compose" onSubmit={async e=>{e.preventDefault();if(await mutate('sendMessage',{groupId:selected.g.id,studentId:selected.id,text:draft},false))setDraft('');}}><input aria-label="اكتب رسالتك" placeholder="اكتب رسالتك هنا..." value={draft} onChange={e=>setDraft(e.target.value)} maxLength={2000} required/><button className="btn primary" disabled={busy||!draft.trim()}><Send size={18}/><span>إرسال</span></button></form></div></div>;}
 function Competitions(){return <><div className="info-banner"><Trophy size={21}/><p>الفرص بتظهر حسب السن، والكورس، والمستويات المكتملة. طلب الطالب يمر بموافقة ولي الأمر وبعدها الإدارة.</p></div><div className="competition-grid">{data.competitions.filter(c=>teacher||isEligible(data,c,me,liveUid?new Date().toISOString().slice(0,10):undefined)||data.registrations.some(r=>r.competitionId===c.id&&r.studentId===me)).map(c=>{const r=data.registrations.find(r=>r.competitionId===c.id&&r.studentId===me);return <article className="competition-card" key={c.id}><div className="competition-art"><Trophy size={64}/><span className="contest-orbit"/><Badge>إعلان توضيحي</Badge></div><div className="competition-body"><small className="eyebrow">BUILD. COMPETE. LEARN.</small><h2>{c.title}</h2><p>{c.description}</p><div className="contest-facts"><span><CalendarDays size={16}/>{fmt(c.date)}</span><span><Users size={16}/>{c.minAge} سنة فأكثر</span><span><Layers size={16}/>{c.minLevels} مستويات روبوتكس</span></div><div className="row spread"><small>التسجيل لحد {fmt(c.deadline)}</small>{r?<Badge status={r.status}/>:!teacher?<button className="btn primary" onClick={()=>mutate('registerCompetition',{id:c.id,studentId:me})} disabled={busy||!isEligible(data,c,me)}>طلب المشاركة<ArrowUpLeft size={16}/></button>:<Badge>{data.registrations.filter(r=>r.competitionId===c.id).length} / {c.capacity} طلب</Badge>}</div>{parent&&r?.status==='pending_parent'&&<button className="btn" onClick={()=>mutate('approveRegistration',{id:r.id})}>موافقة ولي الأمر</button>}</div></article>;})}</div>{!data.competitions.some(c=>teacher||isEligible(data,c,me))&&<Empty title="مفيش مسابقات متاحة ليك حاليًا" description="لما يتوفر تحدّي مناسب لسنّك ومستواك هيظهر هنا."/>}{admin&&<div className="panel next-panel"><h2>طلبات المشاركة</h2>{data.registrations.map(r=><div className="attention-row" key={r.id}><Avatar user={user(r.studentId)} small/><div><b>{user(r.studentId)?.name}</b><small>{data.competitions.find(c=>c.id===r.competitionId)?.title}</small></div><Badge status={r.status}/>{r.status==='pending_admin'&&<button className="btn" onClick={()=>mutate('approveRegistration',{id:r.id})}>اعتماد الطلب</button>}</div>)}{!data.registrations.length&&<Empty title="مفيش طلبات مشاركة لسه"/>}</div>}</>;}
 function Payments(){const items=data.invoices.filter(i=>!parent||i.studentId===childId);return <><div className="info-banner"><CreditCard size={20}/><p>هنا متابعة موعد دفع المستوى وتسجيل التحصيل بواسطة الإدارة. مفيش دفع إلكتروني في المعاينة.</p></div><div className="stats-grid three"><Stat label="إجمالي الاستحقاقات" value={items.reduce((n,i)=>n+i.amount,0)+' ج.م'} detail="سجلات المستويات المعروضة" icon={CreditCard}/><Stat label="تم تسجيل دفعها" value={items.filter(i=>i.status==='paid').reduce((n,i)=>n+i.amount,0)+' ج.م'} detail="بمرجع دفع من الإدارة" icon={CheckCircle2} color="green"/><Stat label="لسه ما اتدفعتش" value={items.filter(i=>i.status==='unpaid').reduce((n,i)=>n+i.amount,0)+' ج.م'} detail="تابع تاريخ الاستحقاق لكل مستوى" icon={Clock} color="orange"/></div><div className="panel table-wrap"><table><thead><tr><th>الطالب</th><th>المجموعة / المستوى</th><th>المبلغ</th><th>موعد الدفع</th><th>الحالة</th><th/></tr></thead><tbody>{items.map(i=><tr key={i.id}><td><b>{user(i.studentId)?.name}</b></td><td>{groupName(i.groupId)}<small className="block">المستوى {i.level}</small></td><td>{i.amount} ج.م</td><td>{fmt(i.due)}</td><td><Badge status={i.status}/>{i.receipt&&<small className="block">{i.receipt}</small>}</td><td>{admin&&i.status==='unpaid'&&<button className="btn small-btn" onClick={()=>setModal({type:'recordPayment',item:i})}>تسجيل الدفع</button>}</td></tr>)}</tbody></table>{!items.length&&<Empty title="مفيش استحقاقات مسجلة"/>}</div><div className="policy-note"><b>سياسة المستويات</b><p>دفع المستوى من أول محاضرة. تأخير الدفع لحد المحاضرة التانية يستلزم متابعة الإدارة قبل الحضور. كل مستوى 4 محاضرات، والمحاضرة ساعتين.</p></div></>;}
 function Analytics(){const required=groups.reduce((n,g)=>n+g.studentIds.length*data.tasks.filter(t=>t.groupId===g.id).length,0),sent=data.submissions.length,complete=data.submissions.filter(s=>s.status==='complete').length;return <><div className="stats-grid"><Stat label="طلاب نشطون" value={allStudents.length} detail="داخل المجموعات الحالية" icon={Users}/><Stat label="إشغال المجموعات" value={Math.round(groups.reduce((n,g)=>n+g.studentIds.length,0)/(groups.length*8||1)*100)+'%'} detail="الحد الأقصى 8 طلاب لكل مجموعة" icon={Layers} color="violet"/><Stat label="إرسال التاسكات" value={Math.round(sent/(required||1)*100)+'%'} detail={`${sent} من ${required} تكليفًا مطلوبًا`} icon={Upload} color="blue"/><Stat label="اعتماد التاسكات" value={Math.round(complete/(required||1)*100)+'%'} detail={`${complete} تاسكات راجعها المدرب`} icon={CheckCircle2} color="green"/></div><div className="analytics-grid"><div className="panel"><div className="section-head"><h2>التقدم حسب المجموعة</h2><Badge>إرسال / اعتماد</Badge></div>{groups.map(g=>{const req=g.studentIds.length*data.tasks.filter(t=>t.groupId===g.id).length,subs=data.submissions.filter(s=>data.tasks.some(t=>t.id===s.taskId&&t.groupId===g.id));return <div className="chart-row" key={g.id}><div className="row spread"><b>{course(g.courseId)?.name}</b><small>{subs.length} / {req}</small></div><div className="double-bar"><span style={{width:(subs.length/(req||1)*100)+'%'}}/><i style={{width:(subs.filter(s=>s.status==='complete').length/(req||1)*100)+'%'}}/></div></div>;})}<div className="chart-key"><span><i className="blue-dot"/>تم الإرسال</span><span><i className="green-dot"/>تم الاعتماد</span></div></div><div className="panel"><h2>حالة التسليمات</h2><div className="donut" style={{background:`conic-gradient(#42b394 0 ${complete/(sent||1)*100}%, #f8b450 ${complete/(sent||1)*100}% ${(complete+pending.length)/(sent||1)*100}%, #aaa2e8 ${(complete+pending.length)/(sent||1)*100}% 100%)`}}><div><strong>{sent}</strong><small>تسليم</small></div></div><div className="row spread"><Badge status="complete">{complete} معتمد</Badge><Badge status="pending">{pending.length} مراجعة</Badge><Badge status="revision">{data.submissions.filter(s=>s.status==='revision').length} تعديل</Badge></div></div></div><div className="panel next-panel"><div className="section-head"><h2>سجل نشاط الأكاديمية</h2><small>آخر {data.audit.length} إجراء</small></div>{data.audit.map(x=><div className="activity-row" key={x.id}><span className="activity-dot"/><div><b>{x.action}</b><small>{user(x.actorId)?.name} · {groupName(x.groupId)}</small></div><time>{fmt(x.createdAt.slice(0,10))}</time></div>)}</div></>;}
 function Integrations(){if(liveUid)return <div className="panel"><h2>ربط Firebase</h2><p>الحسابات والبيانات متصلة بمشروع techware-instructor. بيانات المنصة في academyPortal/techware. بيانات النظام القديم محفوظة في مساراتها؛ ترحيلها للمنصة لم يتم تلقائيًا.</p><p>إدارة الحسابات والكورسات تتيح إضافة البيانات الفعلية. هذه نسخة تجريبية محدودة بحجم الاستعلامات، والتنبيهات تعمل أثناء فتح المنصة.</p></div>;return <><div className="integration-hero"><ShieldCheck size={30}/><div><h2>منظومة واحدة.. مع الحفاظ على الموجود</h2><p>تمت مراجعة الكود المتاح. الربط ببيانات الأكاديمية الفعلية لسه غير مفعّل، والمعاينة دي بتستخدم سجلات توضيحية منفصلة.</p></div></div><div className="integration-grid">{[
 ['Techware Scheduler','مصدر الجداول والمواعيد','تمت مراجعة الكود','salah9604/schedweb','Schedules · courses · rooms','الجداول الحالية بتستخدم أسماء الطلاب والمدربين. محتاجين ربطها بمعرّفات ثابتة قبل المزامنة.'],
 ['Instructor & Attendance','حسابات المدربين والحضور والتقييمات','تمت مراجعة الكود','salah9604/techware-attendance-web','users · attendance · assessments','حضور المدربين منفصل عن حضور الطلاب. التقييمات تُنقل بصلاحيات محددة لكل مجموعة.'],
 ['Firebase / Firestore','المصدر المشترك للبيانات','المشروع محدد','','techware-instructor','يلزم مراجعة قواعد Firestore وStorage الحالية وتفعيل صلاحيات الطالب وولي الأمر قبل التشغيل.'],
 ['Google Drive','ملفات المنهج ومراجع السيشن','مصدر سابق معروف','','فولدر التاسكات والمناهج','نربط مراجع المحاضرات حسب المجموعة. صلاحية الملف لازم تتوافق مع صلاحية الطالب؛ الربط الحي غير مفعّل.'],
 ['الموقع الرسمي','التسجيل والمحتوى العام','الموقع محدد','','techwareacademy.com','استمارة التسجيل تبدأ طلبًا؛ إنشاء الطالب وربطه بولي الأمر بعد مراجعة الإدارة. لا تُنشر بيانات الطلاب أو الأسعار تلقائيًا.'],
 ['Push Notifications','تنبيهات الرسائل والتاسكات','تحتاج تفعيل','','Firebase Cloud Messaging','التنبيهات داخل المعاينة شغالة. الإرسال في الخلفية يحتاج إعداد FCM وإذن الجهاز؛ درجة الإلحاح يحددها النظام والجهاز.']
 ].map(([title,sub,status,repo,code,note])=><article className="panel integration-card" key={title}><div className="row spread"><span className="icon-box blue"><Link2 size={22}/></span><Badge>{status}</Badge></div><h2>{title}</h2><small>{sub}</small><code>{code}</code><p>{note}</p>{repo&&<a href={'https://github.com/'+repo} target="_blank" rel="noreferrer" className="text-btn">فتح المستودع<ExternalLink size={14}/></a>}</article>)}</div><div className="panel next-panel"><h2>قبل تشغيل حسابات الطلاب</h2><div className="launch-list">{['تثبيت studentId وinstructorId وgroupId وربط ولي الأمر بكل ابن.','مراجعة قواعد الوصول واختبار منع قراءة بيانات طالب آخر.','نقل عينة محدودة ومطابقة الجدول والتقييمات قبل التعميم.','تفعيل تسجيل الدخول الخاص بالأكاديمية، ورفع الملفات، وتنبيهات FCM.'].map((x,i)=><p key={i}><span>{i+1}</span>{x}</p>)}</div><a className="btn" href="/Techware_Platform_Specification.html" target="_blank">فتح وثيقة المنصة وخطة الربط<ExternalLink size={16}/></a></div></>;}
 function Events(){return <><div className="panel"><div className="section-head"><h2>إجازات وتحديثات مهمة</h2><small>كل المواعيد بتوقيت مصر</small></div>{data.events.map(e=><div className="event-list-item" key={e.id}><span className="date-tile"><b>{new Date(e.date+'T12:00:00').getDate()}</b><small>{new Date(e.date+'T12:00:00').toLocaleDateString('ar-EG',{month:'short'})}</small></span><div><Badge>{e.type==='holiday'?'إجازة':e.type==='change'?'تغيير استثنائي':'حدث'}</Badge><h3>{e.title}</h3><p>{e.description}</p><small>{e.groupId?groupName(e.groupId):'كل المجموعات'}</small></div></div>)}{!data.events.length&&<Empty title="مفيش أحداث استثنائية"/>}</div><div className="section-head next-panel"><h2>مواعيد المجموعات</h2></div><div className="group-grid">{relevantGroups.map(g=><GroupCard key={g.id} g={g}/>)}</div></>;}
 function NotificationPage(){const ns=data.notifications.filter(n=>n.userId===actorId);return <div className="panel"><div className="section-head"><h2>صندوق الإشعارات</h2><button className="text-btn" onClick={()=>mutate('readNotifications',{},false)}>تحديد الكل كمقروء</button></div><div className="info-banner compact"><Bell size={18}/><span>التنبيهات هنا داخل المنصة. إشعارات الموبايل في الخلفية لسه غير مفعّلة.</span></div>{ns.map(n=><button key={n.id} className={'notification '+(!n.read?'unread':'')} onClick={async()=>{await mutate('readNotifications',{id:n.id},false);navigate(n.kind==='message'?'messages':n.kind==='task'?'tasks':n.kind==='competition'?'competitions':n.kind==='payment'?'payments':'events');}}><span className={'icon-box '+(n.priority==='high'?'orange':'blue')}>{n.kind==='message'?<MessageSquare size={20}/>:<Bell size={20}/>}</span><div><b>{n.title}</b><p>{n.body}</p><small>{fmt(n.createdAt.slice(0,10))}</small></div>{n.priority==='high'&&<Badge status="revision">أولوية عالية</Badge>}{!n.read&&<i className="unread-dot"/>}</button>)}{!ns.length&&<Empty title="كل حاجة هادية" description="أي رسالة أو تحديث جديد هيظهر هنا."/>}</div>;}
 function DialogContent(){if(!modal)return null;const item=modal.item||{},lesson=modal.lesson||{},s=modal.submission;const titles:Record<string,string>={saveGroup:item.id?'تعديل المجموعة':'إنشاء مجموعة جديدة',publishSession:lesson.id?'تعديل ملخص السيشن':'نشر ملخص سيشن وتاسك',submitTask:'تسليم التاسك',viewSubmission:'تفاصيل التسليم',reviewSubmission:'مراجعة التاسك',saveNote:'ملحوظة على متابعة طالب',saveEvent:'إعلان حدث أو إجازة',saveCompetition:'إعلان مسابقة',recordPayment:'تسجيل دفع المستوى',createInvoice:'استحقاق مستوى جديد',addStudent:'إضافة طالب للمعاينة'};
 const groupSelect=<select name="groupId" defaultValue={item.id||groups[0]?.id} required>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select>;
 const attachments=(files:Row[]=[])=>files.map(f=>f.deletedAt?<span key={f.id} className="attachment">{f.name} · تم حذف الصورة بعد انتهاء مدة الاحتفاظ</span>:liveUid?<button type="button" key={f.id} className="btn" onClick={()=>downloadPhoto(f.id).catch(e=>say(portalError(e)))}><Download size={15}/>{f.name}</button>:<a key={f.id} className="attachment" href={f.dataUrl||('/api/files?id='+encodeURIComponent(f.id)+'&actor='+actorId)} download={f.dataUrl?f.name:undefined} target="_blank" rel="noreferrer"><FileText size={17}/>{f.name}<Download size={15}/></a>);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setModal(null);}}><section className="modal" role="dialog" aria-modal="true" aria-label={titles[modal.type]}><div className="modal-header"><div><small>TECHWARE · {roleLabels[role]}</small><h2>{titles[modal.type]}</h2></div><button className="icon-button" aria-label="إغلاق" onClick={()=>setModal(null)} disabled={busy}><X size={22}/></button></div><form onSubmit={formSubmit}><div className="modal-body">
 {modal.type==='saveGroup'&&<><Field label="اسم المجموعة"><input name="name" defaultValue={item.name} required placeholder="مثال: EV3 · صُنّاع المستقبل" maxLength={100}/></Field><div className="form-grid"><Field label="الكورس"><select name="courseId" defaultValue={item.courseId||'ev3'}>{data.courses.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field><Field label="المدرب"><select name="instructorId" defaultValue={item.instructorId||'t1'}>{data.users.filter(u=>u.role==='instructor').map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></Field><Field label="اليوم"><select name="day" defaultValue={item.day||'السبت'}>{['السبت','الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة'].map(d=><option key={d}>{d}</option>)}</select></Field><Field label="الوقت · بتوقيت مصر"><input name="time" type="time" defaultValue={item.time||'12:00'} required/></Field><Field label="القاعة"><input name="room" defaultValue={item.room||'لمبة'} required/></Field><Field label="تاريخ اللقاء القادم"><input name="nextDate" type="date" defaultValue={item.nextDate||(liveUid?new Date().toISOString().slice(0,10):'2026-10-24')} required/></Field><Field label="المستوى"><input name="level" type="number" min="1" max="30" defaultValue={item.level||1} required/></Field><Field label="المحاضرة"><input name="session" type="number" min="1" max="4" defaultValue={item.session||1} required/></Field></div><fieldset><legend>الطلاب · الحد الأقصى 8</legend><div className="check-grid">{allStudents.map(u=><label className="check-option" key={u.id}><input name="studentIds" type="checkbox" value={u.id} defaultChecked={item.studentIds?.includes(u.id)}/><Avatar user={u} small/>{u.name}</label>)}</div></fieldset><div className="info-banner compact"><Clock size={18}/><span>مدة المحاضرة ساعتين. بنراجع تعارض المدرب والقاعة والطلاب وقت الحفظ.</span></div></>}
 {modal.type==='publishSession'&&<><Field label="المجموعة">{groupSelect}</Field><div className="form-grid"><Field label="المستوى"><input type="number" name="level" min="1" max="30" defaultValue={lesson.level||item.level||1} required/></Field><Field label="رقم المحاضرة"><input type="number" name="number" min="1" max="4" defaultValue={lesson.number||item.session||1} required/></Field></div><Field label="تاريخ المحاضرة"><input type="date" name="date" defaultValue={lesson.date||(liveUid?new Date().toISOString().slice(0,10):'2026-10-22')} required/></Field><Field label="عنوان السيشن"><input name="title" defaultValue={lesson.title} required maxLength={150}/></Field><Field label="ملخص السيشن"><textarea name="summary" rows={5} defaultValue={lesson.summary} placeholder="اتعلمنا إيه؟ جرّبنا إيه؟ والهدف من التطبيق؟" required/></Field><Field label="التاسك المطلوب · اختياري"><textarea name="taskText" rows={4} defaultValue={lesson.taskText} placeholder="خطوات واضحة، والناتج المطلوب من الطالب"/></Field><Field label="آخر موعد للتسليم"><input type="date" name="due" defaultValue={data.tasks.find(t=>t.sessionId===lesson.id)?.due||(liveUid?new Date(Date.now()+7*86400000).toISOString().slice(0,10):'2026-10-29')} required/></Field><small>لو نفس المستوى ورقم المحاضرة موجودين، هيتحدّث الملخص مع الحفاظ على تسليمات الطلاب.</small></>}
 {(modal.type==='submitTask'||modal.type==='viewSubmission')&&<><h3 dir="auto">{item.title}</h3><p className="body-copy">{item.description}</p><div className="row spread"><small>آخر موعد {fmt(item.due)}</small><Badge status={s?.status||'missing'}/></div>{s?.feedback&&<div className="feedback"><MessageSquare size={17}/>{s.feedback}</div>}{s&&<details className="previous-sub"><summary>آخر تسليم · المحاولة {s.attempt}</summary><pre>{s.text}</pre>{s.link&&<a target="_blank" rel="noreferrer" href={s.link}>فتح رابط المشروع<ExternalLink size={14}/></a>}{expiresAt(s)&&<p>انتهاء مدة الاحتفاظ بالصور: {fmt(expiresAt(s)!.slice(0,10))}</p>}{attachments(s.files)}{s.history?.map((h:Row,i:number)=><div className="note" key={i}><b>المحاولة {h.attempt}</b><p>{h.text}</p><small>{h.feedback}</small></div>)}</details>}{modal.type==='submitTask'&&s?.status!=='complete'&&<><Field label="إجابتك أو وصف التجربة"><textarea name="text" rows={5} defaultValue={s?.text} placeholder="اشرح عملت إيه، وإيه اللي جرّبته..." maxLength={6000}/></Field><Field label="رابط المشروع · اختياري"><input type="url" name="link" defaultValue={s?.link} placeholder="https://" dir="ltr"/></Field><label className="upload-area"><Upload size={25}/><b>أرفق صورة الكود</b><small>{liveUid?'لحد 5 صور · 220 كيلوبايت للصورة بعد الضغط؛ قص صورة الكود لو كبيرة':'لحد 5 صور · ضغط تلقائي · 2 ميجابايت للصورة بعد الضغط'}</small><input type="file" name="files" multiple accept="image/jpeg,image/png,image/webp"/></label></>}{!s&&modal.type==='viewSubmission'&&<Empty title="لسه ما اتبعتش"/>}</>}
 {modal.type==='reviewSubmission'&&<><div className="row"><Avatar user={user(item.studentId)} small/><div><h3>{user(item.studentId)?.name}</h3><small>{modal.task?.title}</small></div><Badge status={item.status}/></div><pre className="submission-text">{item.text}</pre>{item.link&&<a className="btn" href={item.link} target="_blank" rel="noreferrer">فتح المشروع<ExternalLink size={16}/></a>}{attachments(item.files)}<details className="previous-sub"><summary>المحاولات السابقة ({item.history?.length||0})</summary>{item.history?.map((h:Row,i:number)=><div className="note" key={i}><b>المحاولة {h.attempt}</b><p>{h.text}</p><small>{h.feedback}</small>{attachments(h.files)}</div>)}</details><Field label="حالة التاسك"><select name="status" defaultValue={item.status}><option value="complete">مكتمل ومعتمد</option><option value="revision">محتاج تعديل</option><option value="pending">بانتظار المراجعة</option></select></Field><label className="field"><span><input type="checkbox" name="keepPhotos" defaultChecked={!!item.keepPhotos}/> الاحتفاظ بالصور كمشروع مميز</span></label><p>{liveUid?'الصور المعتمدة متاحة للحذف بعد 90 يوم من المراجعة، باستثناء الصور المحددة للاحتفاظ. التنظيف يعمل عند فتح حساب الإدارة مرة يوميًا، ويمكن تشغيله يدويًا من إدارة الحسابات.':'الصور المعتمدة تُحذف محليًا بعد 90 يوم من المراجعة، إلا لو تم استثناؤها.'}</p><Field label="ملاحظتك للطالب · اختيارية"><textarea name="feedback" rows={4} defaultValue={item.feedback} placeholder="نقطة قوية في الشغل، وخطوة عملية للتحسين"/></Field></>}
 {modal.type==='saveNote'&&<><input type="hidden" name="groupId" value={item.id}/><Field label="الطالب"><select name="studentId">{item.studentIds?.map((id:string)=><option value={id} key={id}>{user(id)?.name}</option>)}</select></Field><Field label="الملحوظة"><textarea name="text" required rows={5}/></Field><Field label="تظهر لمين؟"><select name="visibility"><option value="parent">ولي الأمر والإدارة والمدرب</option><option value="internal">الإدارة والمدرب فقط</option></select></Field></>}
 {modal.type==='saveEvent'&&<><Field label="عنوان الإعلان"><input name="title" required maxLength={160}/></Field><div className="form-grid"><Field label="النوع"><select name="type"><option value="holiday">إجازة</option><option value="change">تغيير معاد أو قاعة</option><option value="event">حدث آخر</option></select></Field><Field label="تاريخ الحدث"><input name="date" type="date" required/></Field></div><Field label="المجموعة"><select name="groupId"><option value="">كل المجموعات</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="التفاصيل"><textarea name="description" required rows={4}/></Field><small>الإعلان يوصل في إشعارات الطلاب وأولياء الأمور والمدربين المعنيين. تعديل معاد المجموعة يتم من شاشة المجموعة.</small></>}
 {modal.type==='saveCompetition'&&<><Field label="اسم المسابقة"><input name="title" required/></Field><Field label="التفاصيل"><textarea name="description" required rows={3}/></Field><div className="form-grid"><Field label="موعد المسابقة"><input type="date" name="date" required/></Field><Field label="آخر تسجيل"><input type="date" name="deadline" required/></Field><Field label="أقل سن بالسنوات"><input type="number" name="minAge" min="4" max="18" defaultValue="13" required/></Field><Field label="مستويات Robotics المكتملة"><input type="number" name="minLevels" min="0" defaultValue="3" required/></Field><Field label="عدد الأماكن"><input type="number" name="capacity" min="1" defaultValue="16" required/></Field></div><fieldset><legend>الكورسات المؤهلة · عدم الاختيار يعني الكل</legend><div className="check-grid">{data.courses.map(c=><label className="check-option" key={c.id}><input type="checkbox" name="courseIds" value={c.id}/>{c.name}</label>)}</div></fieldset></>}
 {modal.type==='recordPayment'&&<><div className="payment-amount">{item.amount}<small>جنيه مصري</small></div><p>{user(item.studentId)?.name} · المستوى {item.level}</p><Field label="رقم الإيصال أو مرجع الدفع"><input name="receipt" required maxLength={100} placeholder="مثال: CASH-1024"/></Field><small>ده تسجيل تحصيل بواسطة الإدارة، مش تنفيذ عملية دفع.</small></>}
 {modal.type==='createInvoice'&&<><Field label="المجموعة">{groupSelect}</Field><Field label="الطالب"><select name="studentId">{allStudents.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></Field><Field label="قيمة المستوى بالجنيه"><input type="number" name="amount" min="1" defaultValue="700" required/></Field><Field label="موعد الدفع"><input type="date" name="due" required/></Field></>}
 {modal.type==='addStudent'&&<><Field label="اسم الطالب"><input name="name" required maxLength={100}/></Field><Field label="السن"><input type="number" name="age" min="4" max="18" required/></Field><small>السجل هنا للمعاينة؛ إنشاء حساب الطالب وربطه بولي الأمر يتطلب تفعيل النظام الفعلي.</small></>}
 </div><div className="modal-footer"><button type="button" className="btn" onClick={()=>setModal(null)} disabled={busy}>إغلاق</button>{modal.type!=='viewSubmission'&&!(modal.type==='submitTask'&&s?.status==='complete')&&<button type="submit" className="btn primary" disabled={busy}>{busy?'جاري الحفظ...':modal.type==='submitTask'?'إرسال للمدرب':modal.type==='publishSession'?'نشر الملخص والتاسك':'حفظ التغييرات'}{!busy&&<Check size={17}/>}</button>}</div></form></section></div>;}
 if(liveUid&&(loading||liveError))return <main className="auth-page"><section className="auth-card"><h1>{loading?'جاري تحميل بياناتك…':'تعذّر فتح المنصة'}</h1><p role="alert">{liveError}</p><button className="btn" onClick={()=>location.reload()}>إعادة المحاولة</button><button className="btn" onClick={()=>signOut(firebaseAuth())}>تسجيل الخروج</button></section></main>;
 return <div className="app-shell"><aside className={'sidebar '+(mobile?'mobile-open':'')}><div className="brand"><span className="brand-mark"><Layers size={30}/></span><div><strong>TECHWARE<span>ACADEMY</span></strong><small>مساحة التعلّم والمتابعة</small></div><button className="mobile-close icon-button" aria-label="إغلاق القائمة" onClick={()=>setMobile(false)}><PanelRightClose size={20}/></button></div><div className="sidebar-section-label">مساحتك</div><nav>{nav.map(n=><button key={n.id} className={(page===n.id||(page==='group'&&n.id==='groups')?'active':'')} onClick={()=>navigate(n.id)}><n.icon size={19}/><span>{n.label}</span>{!!n.count&&<b className="nav-count">{n.count}</b>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-motto"><span className="mini-stars">✦</span><p>بنعلّم نفكّر.<br/>نجرّب. ونبني.</p><small>TECHWARE · SINCE 2018</small></div><div className="side-profile"><Avatar user={actor} small/><div><b>{actor.name}</b><small>{roleLabels[role]} · {liveUid?'حساب الأكاديمية':'حساب توضيحي'}</small></div></div></div></aside>{mobile&&<div className="mobile-scrim" onClick={()=>setMobile(false)}/>}
 <div className="main-shell"><header className="topbar"><div className="row"><button className="icon-button mobile-menu" aria-label="فتح القائمة" onClick={()=>setMobile(true)}><Menu size={23}/></button><span className="breadcrumb">مساحة Techware <ChevronLeft size={14}/><b>{page==='group'?'المجموعة':nav.find(n=>n.id===page)?.label||'الإشعارات'}</b></span></div><div className="top-actions"><span className="today-label">{liveUid?new Date().toLocaleDateString('ar-EG',{timeZone:'Africa/Cairo'}):'الخميس، 22 أكتوبر 2026'} <CalendarDays size={15}/></span><button className="notification-button icon-button" aria-label="فتح الإشعارات" onClick={()=>navigate('notifications')}><Bell size={21}/>{unread>0&&<b>{unread}</b>}</button><Avatar user={actor} small/></div></header>
 <div className="preview-bar">{liveUid?<><span>متصل بـFirebase · {roleLabels[role]}</span><button className="btn small-btn" onClick={()=>signOut(firebaseAuth())}>تسجيل الخروج</button></>:<><span><span className="preview-dot"/>معاينة خاصة <small>· بيانات توضيحية</small></span><div className="role-switch" aria-label="معاينة نوع المستخدم">{(['admin','student','parent','instructor'] as Role[]).map(r=><button key={r} className={role===r?'selected':''} disabled={busy} onClick={()=>switchRole({admin:'a1',student:'s1',parent:'p1',instructor:'t1'}[r])}>{roleLabels[r]}</button>)}</div><small className="save-state"><span className={'status-dot '+(!persistent?'amber':'')}/>{loading?'تحميل...':persistent?'التغييرات محفوظة':'تجربة محلية'}</small></>}</div>
 <main><div className="page-heading"><div><span className="eyebrow">{teacher?'LEARNING OPERATIONS':'MY LEARNING JOURNEY'}</span><h1>{titles[page]}</h1><p>{page==='dashboard'?(admin?'كل التفاصيل اللي تساعدك تتابع، تنظّم، وتاخد الخطوة الصح.':parent?'صورة واضحة عن التعلّم، الالتزام، والتقدم.':'مكانك تتابع فيه التعلّم وتتواصل بسهولة.'):'كل التفاصيل مرتبطة بالمجموعة والطالب، علشان المتابعة تبقى أوضح.'}</p></div>{page==='dashboard'||page==='groups'?commonAction:page==='events'&&admin?<button className="btn primary" onClick={()=>setModal({type:'saveEvent'})}><Plus size={17}/>حدث جديد</button>:page==='competitions'&&admin?<button className="btn primary" onClick={()=>setModal({type:'saveCompetition'})}><Plus size={17}/>مسابقة جديدة</button>:page==='payments'&&admin?<button className="btn primary" onClick={()=>setModal({type:'createInvoice',item:groups[0]})}><Plus size={17}/>استحقاق جديد</button>:page==='analytics'&&admin?<button className="btn primary" onClick={exportReport}><Download size={17}/>تصدير التقرير</button>:page==='group'?<button className="btn" onClick={()=>navigate('groups')}><ArrowRight size={16}/>كل المجموعات</button>:null}</div>
 {parent&&<div className="children-switch"><span>متابعة:</span>{(actor.children||[]).map((id:string)=><button key={id} onClick={()=>{setChildId(id);if(page==='group')navigate('groups');}} className={childId===id?'active':''}><Avatar user={user(id)} small/>{user(id)?.name}</button>)}</div>}
 {!liveUid&&role==='instructor'&&<div className="instructor-choice"><label>معاينة المدرب: <select aria-label="اختيار المدرب للمعاينة" value={actorId} onChange={e=>switchRole(e.target.value)}><option value="t1">مريم أحمد</option><option value="t2">عمر خالد</option></select></label></div>}
 {page==='accounts'&&admin&&<PortalAdmin data={data}/>}
 {page==='dashboard'&&dashboard()}
 {page==='groups'&&<><div className="toolbar"><div className="search-box"><Search size={18}/><input placeholder="ابحث باسم المجموعة أو الكورس..." value={query} onChange={e=>setQuery(e.target.value)}/></div>{admin&&<div className="row"><button className="btn" onClick={()=>liveUid?navigate('accounts'):setModal({type:'addStudent'})}><UserRound size={16}/>طالب جديد</button><button className={'chip '+(filter==='archived'?'active':'')} onClick={()=>setFilter(filter==='archived'?'all':'archived')}><Archive size={16}/>الأرشيف</button></div>}</div><div className="group-grid wide">{(filter==='archived'?data.groups.filter(g=>g.archived):relevantGroups).filter(g=>(g.name+' '+course(g.courseId)?.name).toLowerCase().includes(query.toLowerCase())).map(g=>g.archived?<div className="panel" key={g.id}><Badge>مؤرشفة</Badge><h3>{g.name}</h3><p>المحاضرات والتسليمات محفوظة</p><button className="btn" onClick={()=>mutate('restoreGroup',{id:g.id})}><RotateCcw size={16}/>استعادة</button></div>:<div className="group-wrapper" key={g.id}><GroupCard g={g}/>{admin&&<div className="group-admin-actions"><button onClick={()=>setModal({type:'saveGroup',item:g})}>تعديل</button><button onClick={()=>setModal({type:'confirmArchive',item:g})}>أرشفة</button></div>}</div>)}</div>{filter==='archived'&&!data.groups.some(g=>g.archived)&&<Empty title="الأرشيف فاضي"/>}</>}
 {page==='group'&&GroupDetail()}
 {page==='tasks'&&(teacher?<div className="panel"><div className="search-box"><Search size={18}/><input placeholder="ابحث بالطالب أو التاسك..." value={query} onChange={e=>setQuery(e.target.value)}/></div><ReviewTable/></div>:<><div className="info-banner"><ClipboardList size={20}/><p>نسبة الإرسال بتتحسب من التاسكات المطلوبة. «مكتمل» معناها إن المدرب راجع التسليم واعتمده.</p></div><div className="task-grid">{data.tasks.filter(t=>relevantGroups.some(g=>g.id===t.groupId)).map(t=><TaskCard task={t} key={t.id}/>)}</div></>)}
 {page==='journey'&&Journey()}{page==='messages'&&!parent&&Messages()}{page==='events'&&Events()}{page==='competitions'&&Competitions()}{page==='payments'&&(admin||parent)&&Payments()}{page==='analytics'&&admin&&Analytics()}{page==='integrations'&&admin&&Integrations()}{page==='notifications'&&NotificationPage()}
 <footer><span>Techware Academy · الروبوت مش الهدف… الإنسان هو الهدف.</span><span>العاشر من رمضان · المجاورة التاسعة</span></footer></main></div>
 {modal?.type==='confirmArchive'?<div className="modal-backdrop"><section className="modal small-modal" role="dialog" aria-modal="true" aria-label="أرشفة المجموعة"><div className="modal-body"><Archive size={30}/><h2>أرشفة المجموعة؟</h2><p>مجموعة {modal.item.name} هتنتقل للأرشيف، والمحاضرات والتسليمات هتفضل محفوظة. تقدر تستعيدها بعد كده.</p><div className="row"><button className="btn" onClick={()=>setModal(null)}>إلغاء</button><button className="btn primary" disabled={busy} onClick={()=>mutate('archiveGroup',{id:modal.item.id})}>أرشفة المجموعة</button></div></div></section></div>:DialogContent()}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toast}<button aria-label="إغلاق التنبيه" onClick={()=>setToast('')}><X size={16}/></button></div>}
 </div>;
}
